/*
 * eatsize(): Eat the size spec from a number [eg. 10UL]
 */
private void
eatsize(const char **p)
{
        const char *l = *p;

        if (LOWCASE(*l) == 'u')
                l++;

        switch (LOWCASE(*l)) {
        case 'l':    /* long */
        case 's':    /* short */
        case 'h':    /* short */
        case 'b':    /* char/byte */
        case 'c':    /* char/byte */
                l++;
                /*FALLTHROUGH*/
        default:
                break;
        }

        *p = l;
}

